sp_widget.client_script:
api.controller = function() {
  var c = this;

  c.getOverdueClass = function(daysOverdue) {
    if (daysOverdue > 7) return "overdue-critical";
    if (daysOverdue > 3) return "overdue-warning";
    return "overdue-minor";
  };
};

sp_widget.css:
.ibar-overdue-applications {
  padding: 20px;
}
.ibar-overdue-applications .section-title {
  margin-bottom: 16px;
  font-size: 16px;
  font-weight: 600;
}
.ibar-overdue-applications .overdue-critical {
  background-color: #fdeaea;
}
.ibar-overdue-applications .overdue-warning {
  background-color: #fff8e1;
}
.ibar-overdue-applications .overdue-minor {
  background-color: #fff;
}

sp_widget.script:
(function() {
  data.overdueApplications = [];
  data.count = 0;

  try {
    var now = new GlideDateTime();
    var gr = new GlideRecord("x_1433041_identi_0_application");
    gr.addQuery("active", true);
    gr.addQuery("questionnaire_status", "IN", "draft,in_progress,clarification_requested");
    gr.addNotNullQuery("due_date");
    gr.addQuery("due_date", "<", now.getDisplayValue());
    gr.orderBy("due_date");
    gr.query();

    data.count = gr.getRowCount();

    while (gr.next()) {
      var ownerName = "";
      if (gr.getValue("assigned_owner")) {
        var userGr = new GlideRecord("sys_user");
        if (userGr.get(gr.getValue("assigned_owner"))) {
          ownerName = userGr.getValue("name");
        }
      }

      var dueDate = new GlideDateTime(gr.getValue("due_date"));
      var diff = gs.dateDiff(dueDate.getDisplayValue(), now.getDisplayValue(), true);
      var daysOverdue = Math.floor(parseInt(diff) / 86400);

      data.overdueApplications.push({
        sys_id: gr.getUniqueValue(),
        name: gr.getValue("name"),
        due_date: gr.getDisplayValue("due_date"),
        days_overdue: daysOverdue,
        completion_percent: parseInt(gr.getValue("completion_percent")) || 0,
        owner_name: ownerName,
        escalation_status: gr.getValue("escalation_status"),
        reminder_count: parseInt(gr.getValue("reminder_count")) || 0
      });
    }
  } catch (e) {
    gs.error("IBAR Overdue Applications error: " + e.message);
  }
})();
